 public partial class Editor {
  void EditDevices(){canvas.CancelInteraction();StopPreview();var copy=doc.Clone();using(var dialog=new HardwareManagerDialog(copy))if(dialog.ShowDialog(this)==DialogResult.OK){copy.StructuralCheck();BeginChange();doc=copy;EndChange();}}
