 public sealed class HardwareManagerDialog:Form {
  readonly MapDocument document;readonly string userDirectory;
  readonly ListBox devices=new ListBox();readonly ComboBox templates=new ComboBox();
  readonly PropertyGrid instance=new PropertyGrid(),parameters=new PropertyGrid();readonly TextBox detail=new TextBox();readonly Label status=new Label();
  public HardwareManagerDialog(MapDocument doc):this(doc,HardwareCatalog.UserDirectory){}
  public HardwareManagerDialog(MapDocument doc,string directory){
   document=doc;userDirectory=directory;Text="硬件管理 · 队内模板、实例参数与自建硬件";Size=new Size(1180,800);MinimumSize=new Size(1040,700);StartPosition=FormStartPosition.CenterParent;Font=new Font("Microsoft YaHei UI",10);
   var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=3,RowCount=3};root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,34));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,34));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,32));root.RowStyles.Add(new RowStyle(SizeType.Absolute,100));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));Controls.Add(root);
   var note=new Label{Text="① 从队内/个人模板添加实例  ② 绑定外设与参数  ③ 在航点或状态机选择硬件操作\r\n不改变main固定入口；未知协议须提供真实驱动。定位能力需单独建立观测档案并确认坐标对齐。\r\n内置只读；个人模板可另存/导入/导出，设备保存完整版本快照，更新不会静默改变旧地图。",Dock=DockStyle.Fill};root.Controls.Add(note,0,0);root.SetColumnSpan(note,3);
   var left=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3};left.RowStyles.Add(new RowStyle(SizeType.Absolute,36));left.RowStyles.Add(new RowStyle(SizeType.Percent,100));left.RowStyles.Add(new RowStyle(SizeType.Absolute,155));root.Controls.Add(left,0,1);templates.Dock=DockStyle.Fill;templates.DropDownStyle=ComboBoxStyle.DropDownList;templates.DropDownWidth=600;left.Controls.Add(templates);devices.Dock=DockStyle.Fill;devices.HorizontalScrollbar=true;left.Controls.Add(devices);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill};left.Controls.Add(buttons);
   Button(buttons,"添加实例",AddInstance);Button(buttons,"移除实例",RemoveInstance);Button(buttons,"更新模板",UpdateInstance);Button(buttons,"设为定位源",MakeObservation);Button(buttons,"新建模板…",NewTemplate);Button(buttons,"编辑个人模板…",EditPersonalTemplate);Button(buttons,"复制为个人模板…",CopyTemplate);Button(buttons,"导入模板…",ImportTemplate);Button(buttons,"导出模板…",ExportTemplate);
   var middle=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2};middle.RowStyles.Add(new RowStyle(SizeType.Absolute,190));middle.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.Controls.Add(middle,1,1);instance.Dock=parameters.Dock=DockStyle.Fill;instance.ToolbarVisible=parameters.ToolbarVisible=false;instance.PropertySort=parameters.PropertySort=PropertySort.NoSort;middle.Controls.Add(instance);middle.Controls.Add(parameters);
   detail.Multiline=true;detail.ReadOnly=true;detail.Dock=DockStyle.Fill;detail.ScrollBars=ScrollBars.Vertical;detail.BackColor=Color.FromArgb(244,248,252);root.Controls.Add(detail,2,1);
   var footer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));footer.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,230));root.Controls.Add(footer,0,2);root.SetColumnSpan(footer,3);status.Dock=DockStyle.Fill;status.AutoEllipsis=true;footer.Controls.Add(status);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};footer.Controls.Add(actions);var ok=new Button{Text="确定",Width=100,Height=34};ok.Click+=(s,e)=>{try{parameters.Focus();document.StructuralCheck();DialogResult=DialogResult.OK;}catch(Exception error){MessageBox.Show(this,error.Message,"硬件配置未完成");}};actions.Controls.Add(ok);var cancel=new Button{Text="取消",DialogResult=DialogResult.Cancel,Width=100,Height=34};actions.Controls.Add(cancel);CancelButton=cancel;
   devices.SelectedIndexChanged+=(s,e)=>ShowInstance();instance.PropertyValueChanged+=(s,e)=>{devices.Refresh();ShowDetails();};parameters.PropertyValueChanged+=(s,e)=>{try{HardwareRules.Structure(document);status.Text="参数已更新，导出前仍需确认真实接线和标定。";}catch(Exception error){e.ChangedItem.PropertyDescriptor.SetValue(parameters.SelectedObject,e.OldValue);parameters.Refresh();status.Text=error.Message;}ShowDetails();};ReloadTemplates();RefreshDevices();
  }
  static void Button(Control parent,string text,Action call){var b=new Button{Text=text,AutoSize=true,Height=31};b.Click+=(s,e)=>{try{call();}catch(Exception error){MessageBox.Show(parent.FindForm(),error.Message,"硬件操作未完成");}};parent.Controls.Add(b);}
  DeviceInstance Current {get{return devices.SelectedItem as DeviceInstance;}}
  DeviceTemplate SelectedTemplate {get{return templates.SelectedItem as DeviceTemplate;}}
  void ReloadTemplates(string select=null){templates.Items.Clear();try{templates.Items.AddRange(HardwareCatalog.LoadTemplates(userDirectory).Cast<object>().ToArray());}catch(Exception e){templates.Items.AddRange(HardwareCatalog.Builtins().Cast<object>().ToArray());status.Text="个人模板目录读取失败；保留原文件，仅显示内置模板："+e.Message;}if(templates.Items.Count>0){int chosen=0;for(int i=0;i<templates.Items.Count;i++)if(((DeviceTemplate)templates.Items[i]).Id==select)chosen=i;templates.SelectedIndex=chosen;}}
  void RefreshDevices(int selected=0){devices.Items.Clear();devices.Items.AddRange(HardwareRules.Devices(document).Cast<object>().ToArray());if(devices.Items.Count>0)devices.SelectedIndex=Math.Min(Math.Max(0,selected),devices.Items.Count-1);else ShowInstance();}
  public DeviceInstance Add(DeviceTemplate template){var device=HardwareCatalog.Create(template);if(document.Devices==null)document.Devices=new List<DeviceInstance>();int n=1;string original=device.Name;while(document.Devices.Any(d=>d.Name==device.Name))device.Name=original+" "+(++n);document.Devices.Add(device);document.Version=8;try{document.StructuralCheck();}catch{document.Devices.Remove(device);throw;}RefreshDevices(document.Devices.Count-1);return device;}
  void AddInstance(){if(SelectedTemplate!=null)Add(SelectedTemplate);}
  public void Remove(DeviceInstance device){if(HardwareRules.Referenced(document,device.Id))throw new Exception("仍有航点、状态机或纠错引用此设备；请先移除相关操作。");document.Devices.Remove(device);if(!String.IsNullOrEmpty(device.ObservationSourceId)&&document.HardwareSources!=null)document.HardwareSources.RemoveAll(s=>s.Id==device.ObservationSourceId);RefreshDevices();status.Text="实例已移除；导出时同步移除工程登记，手改文件由事务保护保留。";}
  void RemoveInstance(){if(Current!=null)Remove(Current);}
  void ShowInstance(){instance.SelectedObject=Current;parameters.SelectedObject=Current==null?null:new DeviceParameterView(Current);ShowDetails();}
  void ShowDetails(){var d=Current;if(d==null){detail.Text="从上方选择模板并添加实例。个人模板目录：\r\n"+userDirectory;return;}var t=d.Template;detail.Text="实例："+d.Name+"\r\nID："+d.Id+"\r\n模板："+t.Name+" "+t.Version+"\r\n平台："+t.Platform+"\r\n驱动："+t.DriverKind+"\r\n声明的验证等级："+t.Verified+"\r\n服务周期："+t.PeriodMs+" ms\r\n最小堆空间："+t.MinHeapBytes+" bytes\r\n实例上限："+t.MaxInstances+"\r\n\r\n资源声明：\r\n"+String.Join("\r\n",t.Resources.Select(r=>r.Kind+" = "+HardwareRules.ExpandResource(r.Value,d)).ToArray())+"\r\n\r\n可用操作：\r\n"+String.Join("\r\n",t.Operations.Select(o=>o.ToString()).ToArray())+"\r\n\r\n"+t.Note+"\r\n\r\n模板快照SHA256：\r\n"+d.TemplateSha256;}
  void UpdateInstance(){if(Current==null||SelectedTemplate==null)return;if(Current.TemplateId!=SelectedTemplate.Id)throw new Exception("更新只接受相同模板ID；更换设备类型请新建实例。");var previous=Current.Template;string oldSha=Current.TemplateSha256,oldVersion=Current.TemplateVersion;var next=HardwareCatalog.Snapshot(SelectedTemplate);if(next.Version==previous.Version&&HardwareCatalog.Hash(next)!=oldSha)throw new Exception("同版本不同内容不能替换设备快照。");var values=new Dictionary<string,string>(Current.Values);Current.Template=next;Current.TemplateVersion=next.Version;Current.TemplateSha256=HardwareCatalog.Hash(next);Current.Values=next.Parameters.ToDictionary(p=>p.Key,p=>values.ContainsKey(p.Key)?values[p.Key]:p.Default);try{document.StructuralCheck();}catch{Current.Template=previous;Current.TemplateSha256=oldSha;Current.TemplateVersion=oldVersion;Current.Values=values;throw;}Current.Configured=false;ShowInstance();status.Text="已明确更新模板；请重新确认接线和参数。";}
  public HardwareSource Observation(DeviceInstance device){if(device.Template.ObservationAxes==0)throw new Exception("此模板没有独立定位观测能力。");if(document.HardwareSources==null)document.HardwareSources=new List<HardwareSource>();var previous=document.HardwareSources.FirstOrDefault(s=>s.Id==device.ObservationSourceId);if(previous!=null)return previous;var source=new HardwareSource{Name=device.Name+"观测",Kind=String.IsNullOrEmpty(device.Template.ObservationKind)?"external_pose":device.Template.ObservationKind,Axes=device.Template.ObservationAxes,Reference="relative",Independent=true,DriverHeader="rcs_hw.h",ReadFunction="rcs_hw_observation_"+device.Id};document.HardwareSources.Add(source);device.ObservationSourceId=source.Id;document.Version=8;return source;}
  void MakeObservation(){if(Current==null)return;var source=Observation(Current);status.Text="已创建定位档案："+source.Name+"。请在定位硬件窗口确认地图对齐后再启用纠错。";}
  void NewTemplate(){using(var dialog=new HardwareTemplateDialog(null,userDirectory))if(dialog.ShowDialog(this)==DialogResult.OK)ReloadTemplates(dialog.Result.Id);}
  void EditPersonalTemplate(){if(SelectedTemplate==null)return;if(HardwareCatalog.Builtins().Any(t=>t.Id==SelectedTemplate.Id))throw new Exception("内置模板只读，请先复制为个人模板。");using(var dialog=new HardwareTemplateDialog(SelectedTemplate,userDirectory))if(dialog.ShowDialog(this)==DialogResult.OK)ReloadTemplates(dialog.Result.Id);}
  void CopyTemplate(){if(SelectedTemplate==null)return;var copy=HardwareCatalog.Snapshot(SelectedTemplate);copy.Id="user_"+Guid.NewGuid().ToString("N");copy.Name+="（个人副本）";copy.Version="1.0.0";copy.Verified="none";using(var dialog=new HardwareTemplateDialog(copy,userDirectory))if(dialog.ShowDialog(this)==DialogResult.OK)ReloadTemplates(dialog.Result.Id);}
  void ImportTemplate(){using(var file=new OpenFileDialog{Filter="硬件模板包|*.rcshw.json|JSON|*.json"})if(file.ShowDialog(this)==DialogResult.OK){string target=HardwareCatalog.Import(file.FileName,userDirectory);ReloadTemplates();status.Text="已导入个人模板："+target;}}
  void ExportTemplate(){if(SelectedTemplate==null)return;using(var file=new SaveFileDialog{Filter="硬件模板包|*.rcshw.json",FileName=SelectedTemplate.Id+"-"+SelectedTemplate.Version+".rcshw.json"})if(file.ShowDialog(this)==DialogResult.OK)File.WriteAllText(file.FileName,HardwareCatalog.Json(HardwareCatalog.Snapshot(SelectedTemplate)),new UTF8Encoding(false));}
 }

 // 参数使用声明的类型显示，不把GPIO/定时器句柄当自由C代码。
 public sealed class DeviceParameterView:ICustomTypeDescriptor {
  readonly DeviceInstance instance;public DeviceParameterView(DeviceInstance value){instance=value;}
  public AttributeCollection GetAttributes(){return AttributeCollection.Empty;}public string GetClassName(){return "设备参数";}public string GetComponentName(){return instance.Name;}public TypeConverter GetConverter(){return new TypeConverter();}public EventDescriptor GetDefaultEvent(){return null;}public PropertyDescriptor GetDefaultProperty(){return null;}public object GetEditor(Type editorBaseType){return null;}public EventDescriptorCollection GetEvents(Attribute[] attributes){return EventDescriptorCollection.Empty;}public EventDescriptorCollection GetEvents(){return EventDescriptorCollection.Empty;}public object GetPropertyOwner(PropertyDescriptor pd){return this;}
  public PropertyDescriptorCollection GetProperties(){return GetProperties(null);}public PropertyDescriptorCollection GetProperties(Attribute[] attributes){return new PropertyDescriptorCollection(instance.Template.Parameters.Select(p=>(PropertyDescriptor)new ParameterDescriptor(instance,p)).ToArray());}
  sealed class ParameterDescriptor:PropertyDescriptor {
   readonly DeviceInstance instance;readonly DeviceParameter parameter;
   public ParameterDescriptor(DeviceInstance i,DeviceParameter p):base(p.Key,new Attribute[]{new DisplayNameAttribute(p.Name),new DescriptionAttribute(p.Description??""),new CategoryAttribute("设备绑定参数")}){instance=i;parameter=p;}
   public override Type ComponentType{get{return typeof(DeviceParameterView);}}public override bool IsReadOnly{get{return false;}}public override Type PropertyType{get{return parameter.Type=="bool"?typeof(bool):parameter.Type=="int"?typeof(int):parameter.Type=="float"?typeof(double):typeof(string);}}
   public override object GetValue(object component){string value=instance.Get(parameter.Key);return parameter.Type=="bool"?(object)(value=="1"||value=="true"):parameter.Type=="int"?(object)checked((int)Double.Parse(value,CultureInfo.InvariantCulture)):parameter.Type=="float"?(object)Double.Parse(value,CultureInfo.InvariantCulture):(object)value;}
   public override void SetValue(object component,object value){string text=parameter.Type=="bool"?((bool)value?"true":"false"):Convert.ToString(value,CultureInfo.InvariantCulture);HardwareRules.ParameterValue(parameter,text);instance.Values[parameter.Key]=text;instance.Configured=false;}
   public override bool CanResetValue(object component){return true;}public override void ResetValue(object component){instance.Values[parameter.Key]=parameter.Default;instance.Configured=false;}public override bool ShouldSerializeValue(object component){return true;}
   public override TypeConverter Converter{get{return parameter.Type=="choice"?new ChoiceConverter(parameter.Choices):base.Converter;}}
  }
  sealed class ChoiceConverter:StringConverter {readonly List<string> choices;public ChoiceConverter(List<string> v){choices=v;}public override bool GetStandardValuesSupported(ITypeDescriptorContext context){return true;}public override bool GetStandardValuesExclusive(ITypeDescriptorContext context){return true;}public override StandardValuesCollection GetStandardValues(ITypeDescriptorContext context){return new StandardValuesCollection(choices);}}
 }
